import os
import tomllib

class ConfigError(Exception):
    pass

def load_config(defaults, toml_path=None, env_prefix='', env=None):
    if env is None:
        env = os.environ
    config = defaults.copy()
    if toml_path:
        try:
            with open(toml_path, 'rb') as f:
                toml_config = tomllib.load(f)
                config.update(tomllib.load(f))
        except FileNotFoundError:
            pass
    for key, value in env.items():
        if key.startswith(env_prefix):
            path = key[len(env_prefix):].lower().split('__')
            current = config
            for part in path[:-1]:
                if part not in current:
                    current[part] = {}
                current = current[part]
            current[path[-1]] = value
    return config

import pytest
from envcfg import load_config, ConfigError

def test_defaults():
    defaults = {'a': 1, 'b': 2}
    assert load_config(defaults) == {'a': 1, 'b': 2}

def test_toml():
    toml_content = b'a = 1\nb = 2'
    with open('config.toml', 'wb') as f:
        f.write(toml_content)
    assert load_config({}, 'config.toml') == {'a': 1, 'b': 2}

def test_env():
    os.environ['APP__A'] = '3'
    assert load_config({'a': 1}, env_prefix='APP__') == {'a': 3}

def test_precedence():
    toml_content = b'a = 2'
    os.environ['APP__A'] = '3'
    with open('config.toml', 'wb') as f:
        f.write(toml_content)
    assert load_config({'a': 1}, 'config.toml', env_prefix='APP__') == {'a': 3}

def test_nested():
    toml_content = b'[server]\nport = 8080'
    os.environ['APP__SERVER__PORT'] = '8081'
    with open('config.toml', 'wb') as f:
        f.write(toml_content)
    assert load_config({'server': {'port': 8080}}, 'config.toml', env_prefix='APP__') == {'server': {'port': 8081}}

def test_coercion():
    os.environ['APP__A'] = 'true'
    assert load_config({'a': False}, env_prefix='APP__') == {'a': True}

def test_error():
    os.environ['APP__A'] = 'three'
    with pytest.raises(ConfigError):
        load_config({'a': 1}, env_prefix='APP__')

